export class ChatOrchestrator {
  constructor(
    private readonly store: LocalStore,
    private readonly data: LocalDataService,
    private readonly memory: LocalMemoryService,
  ) {}

  async stream(
    request: {
      base_url: string;
      api_key: string;
      model: string;
      messages: ChatMessage[];
      brief?: { product_name?: string } | null;
      conversation_id?: string | null;
    },
    onEvent: (event: RawSseEvent) => void,
    signal?: AbortSignal,
  ): Promise<void> {
    const provider: Provider = isEndpointConfigured(request)
      ? "endpoint"
      : "deterministic";
    emit(
      {
        event: "status",
        data: { phase: provider === "endpoint" ? "streaming" : "thinking" },
      },
      onEvent,
    );

    const conversation = await this.ensureConversation(request.conversation_id);
    emit({ event: "conversation", data: { id: conversation.id } }, onEvent);

    const userMessage =
      request.messages[request.messages.length - 1]?.content ?? "";
    await this.memory.appendTurn(conversation.id, "user", userMessage);

    if (provider === "endpoint") {
      await this.streamEndpoint(request, conversation, onEvent, signal);
    } else {
      await this.streamDeterministic(request, conversation, onEvent);
    }
  }

  private async ensureConversation(
    conversationId: string | undefined | null,
  ): Promise<{
    id: string;
    title: string;
    created_at: string;
    updated_at: string;
  }> {
    if (conversationId) {
      const existing = await this.store.getConversation(conversationId);
      if (existing) {
        return existing;
      }
    }
    const latest = await this.memory.latestConversation();
    if (latest.conversation) {
      return latest.conversation;
    }
    return this.memory.createConversation("New conversation");
  }

  private async streamDeterministic(
    request: { messages: ChatMessage[] },
    conversation: { id: string; title: string },
    onEvent: (event: RawSseEvent) => void,
  ): Promise<void> {
    const message = request.messages[request.messages.length - 1]?.content ?? "";
    const canvas = await this.data.fetchCanvas();
    emit(toolEvent("get_canvas", "success", `${canvas.jobs.length} jobs`), onEvent);
    emit({ event: "canvas_dirty", data: {} }, onEvent);

    const content = this.deterministicAnswer(message, canvas);
    emit({ event: "delta", data: { text: content } }, onEvent);
    emit({ event: "message", data: { content } }, onEvent);
    await this.memory.appendTurn(conversation.id, "assistant", content);
  }

  private deterministicAnswer(message: string, canvas: CanvasData): string {
    const lower = message.toLowerCase();
    if (lower.includes("remember")) {
      return "I’ve saved that to memory. What would you like to do with it?";
    }
    if (lower.includes("render") || lower.includes("board")) {
      const outcomes = canvas.outcomes.slice(0, 6);
      if (!outcomes.length) {
        return "Add an outcome first, then I can render the opportunity board.";
      }
      return "Here is your opportunity board, ranked by ODI opportunity score.";
    }
    const jobs = canvas.jobs.length;
    const steps = canvas.steps.length;
    const outcomes = canvas.outcomes.length;
    const scored = canvas.outcomes.filter((o) => o.opportunity_score !== null);
