async function withLocal<T>(
  sidecar: () => Promise<T>,
  local: (bff: Awaited<ReturnType<typeof getStudioBff>>) => Promise<T>,
): Promise<T> {
  try {
    return await sidecar();
  } catch (error) {
    // Application failures from the sidecar are real failures; only transport
