   function launch() {
     if (!activeGoal) {
       return;
     }
     complete();
     if (activeGoal.destination.kind === "setup") {
       openSetup();
     } else if (activeGoal.destination.kind === "chat") {
       // Some starting points are a conversation, not a view: close the setup
       // questions so the chosen thread has the stage.
       closeSetup();
