-                Skip the tour
-              </button>
+              <>
+                <button type="button" className="wizard-text-button" onClick={skip}>
+                  Skip the tour
+                </button>
+                <button type="button" className="wizard-text-button" onClick={skipStep}>
+                  Skip this step
+                </button>
+              </>
             ) : null}
           </div>
           <div className="wizard-footer__actions">
             {stepIndex > 0 ? (
               <button
                 type="button"
                 className="button button--ghost"
                 onClick={back}
               >
                 Back
               </button>
             ) : null}

             {stepId === "launch" ? (
               <button
                 type="button"
                 className="button wizard-button--primary"
                 onClick={launch}
                 disabled={!activeGoal}
               >
                 {activeGoal?.cta ?? "Continue"}
               </button>
             ) : (
               <button
                 type="button"
                 className="button wizard-button--primary"
                 onClick={advance}
                 disabled={stepId === "goal" && state.goal === null}
               >
                 Continue
               </button>
             )}
           </div>
         </footer>
       </div>
     </div>
   );
 }

