   border-radius: var(--r-pill);
   background: color-mix(in srgb, var(--amber) 10%, transparent);
   color: var(--amber);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   white-space: nowrap;
 }

 .demo__disclaimer {
   color: var(--faint);
   font-size: 0.875rem;
   line-height: 1.5;
 }

 .demo__disclaimer a {
   color: var(--muted);
   text-decoration: underline;
   text-underline-offset: 3px;
 }

 .demo__disclaimer a:hover {
   color: var(--text);
 }

 .demo__frame {
   overflow: hidden;
   border-radius: var(--r-lg);
   background: var(--bg-raised);
 }

 .demo__bar {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 12px;
   height: 46px;
   padding: 0 16px;
   border-bottom: 1px solid var(--line);
 }

 .demo__brand {
   display: inline-flex;
   align-items: center;
   gap: 9px;
   font-size: 0.8125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .demo__health {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   padding: 4px 11px;
   border: 1px solid var(--line);
   border-radius: var(--r-pill);
   color: var(--faint);
   font-size: 0.6875rem;
 }

 .demo__dot {
   width: 6px;
   height: 6px;
   border-radius: 50%;
   background: var(--green);
   box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 14%, transparent);
 }

 .demo__transcript,
 .demo__live {
   padding: 22px;
 }

 .demo__thread {
   min-height: 280px;
 }

 .demo__exchange + .demo__exchange {
   margin-top: 22px;
 }

 .demo__msg {
   display: flex;
   gap: 12px;
 }

 .demo__msg + .demo__msg {
   margin-top: 18px;
 }

 .demo__msg--user {
   justify-content: flex-end;
 }

 .demo__msg--assistant {
   align-items: flex-start;
   transition:
     opacity 0.5s var(--ease-apple-out),
     transform 0.5s var(--ease-apple-out);
 }

 .demo__msg--assistant.is-pending {
   opacity: 0;
   transform: translateY(8px);
 }

 .demo__bubble {
   max-width: 78%;
   padding: 10px 14px;
   border: 1px solid var(--line);
   border-radius: 18px 18px 6px 18px;
   background: var(--surface-hover);
   font-size: 0.9375rem;
   line-height: 1.55;
   white-space: pre-wrap;
   overflow-wrap: anywhere;
 }

 .demo__msg-body {
   flex: 1;
   min-width: 0;
   display: flex;
   flex-direction: column;
   gap: 14px;
 }

 .demo__reply {
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 .demo__avatar {
   display: grid;
   place-items: center;
   width: 26px;
   height: 26px;
   flex: none;
   margin-top: 2px;
   border-radius: 8px;
   background: linear-gradient(140deg, var(--accent-strong), var(--accent));
   color: var(--bg);
 }

 .demo__typing {
   display: flex;
   align-items: center;
   gap: 9px;
   margin-top: 18px;
 }

 .typing__dots {
   display: inline-flex;
   gap: 3px;
 }

 .typing__dots i {
   width: 5px;
   height: 5px;
   border-radius: 50%;
   background: var(--faint);
   animation: caret-blink 1.2s infinite ease-in-out;
 }

 .typing__dots i:nth-child(2) { animation-delay: 0.15s; }
 .typing__dots i:nth-child(3) { animation-delay: 0.3s; }

 .demo__composer {
   display: flex;
   align-items: flex-end;
   gap: 10px;
   margin-top: 18px;
   padding: 8px 9px 8px 16px;
   border: 1px solid var(--line);
   border-radius: 22px;
   background: var(--surface);
   transition: border-color 0.16s var(--ease-tactile);
 }

 .demo__composer:focus-within {
   border-color: color-mix(in srgb, var(--accent) 42%, transparent);
 }

 .demo__input {
   flex: 1;
   min-width: 0;
   max-height: 140px;
   padding: 8px 0;
   border: 0;
   background: transparent;
   color: var(--text);
   font-size: 0.9375rem;
   line-height: 1.5;
   resize: none;
   outline: none;
 }

 .demo__input::placeholder {
   color: var(--faint);
 }

 .demo__send {
   display: grid;
   place-items: center;
   width: 34px;
   height: 34px;
   flex: none;
   border-radius: 50%;
   background: var(--text);
   color: var(--bg);
   transition:
     transform 0.15s var(--ease-tactile),
     opacity 0.15s var(--ease-tactile);
 }

 .demo__send:hover {
   transform: translateY(-1px);
 }

 .demo__chips {
   display: flex;
   flex-wrap: wrap;
   gap: 7px;
   margin-top: 14px;
 }

 .demo__chip {
   display: inline-flex;
   align-items: center;
   padding: 6px 12px;
   border: 1px solid var(--line);
   border-radius: var(--r-pill);
   background: var(--surface);
   color: var(--muted);
   font-size: 0.8125rem;
   text-align: left;
   transition:
     background-color 0.15s var(--ease-tactile),
     border-color 0.15s var(--ease-tactile),
     color 0.15s var(--ease-tactile),
     transform 0.15s var(--ease-tactile);
 }

 .demo__chip:hover {
   transform: translateY(-1px);
   border-color: var(--line-strong);
   background: var(--surface-hover);
   color: var(--text);
 }

 /* ---------------------------------------------------------------- */
 /* Run it                                                           */
 /* ---------------------------------------------------------------- */

 .run {
   display: flex;
   flex-direction: column;
   gap: 32px;
 }

 .run__grid {
   display: grid;
   gap: 28px;
   grid-template-columns: minmax(0, 1fr);
 }

 @media (min-width: 960px) {
   .run__grid {
     grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
   }
 }

 .run__label {
   margin-bottom: 12px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .run__note {
   color: var(--muted);
   font-size: 0.9375rem;
 }

 .copy-btn--inline {
   position: static;
   flex: none;
   padding: 3px 9px;
   font-size: 0.6875rem;
   opacity: 1;
 }

 .section__more {
   margin-top: 32px;
 }

 .status-note--muted {
   margin-top: 10px;
   font-weight: 400;
   color: var(--muted);
 }

 /* ---------------------------------------------------------------- */
 /* Documentation                                                     */
 /* ---------------------------------------------------------------- */

 .doc {
   display: grid;
   gap: clamp(32px, 5vw, 64px);
   grid-template-columns: minmax(0, 1fr);
   max-width: var(--w-wide);
   margin-inline: auto;
   padding: clamp(40px, 6vw, 72px) var(--gutter) clamp(72px, 9vw, 140px);
 }

 @media (min-width: 900px) {
   .doc {
     grid-template-columns: 230px minmax(0, 1fr);
   }
 }

 .doc__nav {
   display: flex;
   flex-direction: column;
   gap: 28px;
 }

 @media (min-width: 900px) {
   .doc__nav {
     position: sticky;
     top: 96px;
     align-self: start;
     max-height: calc(100vh - 140px);
     overflow-y: auto;
   }
 }

 .doc__back {
   font-size: 0.8125rem;
   color: var(--muted);
 }

 .doc__back:hover {
   color: var(--text);
 }

 .doc__group-title {
   margin-bottom: 10px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.12em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .doc__list {
   display: flex;
   flex-direction: column;
   gap: 2px;
   margin: 0;
   padding: 0;
   list-style: none;
 }

 .doc__link {
   display: block;
   padding: 6px 10px;
   border-radius: var(--r-sm);
   color: var(--muted);
   font-size: 0.875rem;
   transition: background-color 0.15s var(--ease-tactile), color 0.15s var(--ease-tactile);
 }

 .doc__link:hover {
   background: var(--surface);
   color: var(--text);
 }

 .doc__link.is-current {
   background: var(--surface-hover);
   color: var(--text);
   font-weight: 600;
 }

 .doc__body {
   min-width: 0;
 }

 .doc__head {
   margin-bottom: 40px;
   padding-bottom: 32px;
   border-bottom: 1px solid var(--line);
 }

 .doc__title {
   font-size: clamp(2rem, 4.5vw, 3rem);
   font-weight: 600;
   letter-spacing: -0.035em;
   line-height: 1.05;
   text-wrap: balance;
 }

 .doc__lede {
   max-width: 62ch;
   margin-bottom: 32px;
   color: var(--muted);
   font-size: 1.0625rem;
   line-height: 1.6;
 }

 .prose__source {
   margin-top: 48px;
   padding-top: 20px;
   border-top: 1px solid var(--line);
   font-size: 0.875rem;
   color: var(--faint);
 }

 .doc__toc {
   margin-top: 48px;
   padding: 20px 24px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--surface);
 }

 .doc__toc-title {
   margin-bottom: 10px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.12em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .doc__toc ul {
   display: flex;
   flex-direction: column;
   gap: 4px;
   margin: 0;
   padding: 0;
   list-style: none;
 }

 .doc__toc-item a {
   color: var(--muted);
   font-size: 0.875rem;
 }

 .doc__toc-item a:hover {
   color: var(--text);
 }

 .doc__toc-item--3 {
   padding-left: 14px;
 }

 .doc__pager {
   display: flex;
   flex-wrap: wrap;
   justify-content: space-between;
   gap: 12px;
   margin-top: 56px;
   padding-top: 28px;
   border-top: 1px solid var(--line);
 }

 .doc__pager-link {
   display: flex;
   flex-direction: column;
   gap: 4px;
   padding: 14px 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--surface);
   transition: border-color 0.15s var(--ease-tactile), transform 0.15s var(--ease-tactile);
 }

 .doc__pager-link:hover {
   border-color: var(--line-strong);
   transform: translateY(-1px);
 }

 .doc__pager-link--next {
   margin-left: auto;
   text-align: right;
 }

 .doc__pager-label {
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .doc__pager-title {
   color: var(--text);
   font-size: 0.9375rem;
   font-weight: 600;
 }

 /* The docs index. */
 .doc-index__group + .doc-index__group {
   margin-top: 48px;
 }

 .doc-index__title {
   margin-bottom: 18px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.12em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .doc-index__card {
   display: flex;
   flex-direction: column;
   gap: 8px;
   padding: 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--surface);
   color: var(--text);
   transition:
     transform 0.2s var(--ease-apple-out),
     border-color 0.2s var(--ease-apple-out);
 }

 .doc-index__card:hover {
   transform: translateY(-2px);
   border-color: var(--line-strong);
 }

 .doc-index__name {
   font-size: 0.9375rem;
   font-weight: 600;
 }

 .doc-index__blurb {
   color: var(--muted);
   font-size: 0.8125rem;
   line-height: 1.55;
 }

 .doc-index__note {
   margin-top: 48px;
   color: var(--muted);
   font-size: 0.9375rem;
 }

 /* The tool reference. */
 .tool-index {
   display: flex;
   flex-wrap: wrap;
   gap: 6px;
   margin-bottom: 44px;
   padding: 16px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--surface);
 }

 .tool-index__link {
   padding: 4px 10px;
   border-radius: var(--r-pill);
   font-family: var(--mono);
   font-size: 0.75rem;
   color: var(--muted);
 }

 .tool-index__link:hover {
   background: var(--surface-hover);
   color: var(--text);
 }

 .tool-doc {
   padding-top: 32px;
   border-top: 1px solid var(--line);
   scroll-margin-top: 96px;
 }

 .tool-doc + .tool-doc {
   margin-top: 40px;
 }

 .tool-doc__name {
   display: flex;
   flex-wrap: wrap;
   align-items: center;
   gap: 12px;
   font-family: var(--mono);
   font-size: 1.0625rem;
   font-weight: 600;
   color: var(--text);
 }

 .tool-doc__purpose {
   margin: 10px 0 16px;
   color: var(--muted);
   font-size: 0.9375rem;
 }

 .tool-doc__args {
   width: 100%;
   margin-top: 16px;
   border-collapse: collapse;
   font-size: 0.8125rem;
 }

 .tool-doc__args th,
 .tool-doc__args td {
   padding: 9px 12px;
   border-bottom: 1px solid var(--line);
   text-align: left;
   vertical-align: top;
 }

 .tool-doc__args th {
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .tool-doc__args code {
   font-family: var(--mono);
   color: var(--text);
 }

 .schema {
   margin-top: 16px;
 }

 .schema__summary {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   padding: 8px 16px;
   border: 1px solid var(--line);
   border-radius: var(--r-pill);
   background: var(--surface);
   color: var(--muted);
   font-size: 0.875rem;
   cursor: pointer;
   list-style: none;
   transition: border-color 0.15s var(--ease-tactile), color 0.15s var(--ease-tactile);
 }

 .schema__summary::-webkit-details-marker {
   display: none;
 }

 .schema__summary::before {
   content: "+";
   font-family: var(--mono);
   color: var(--accent);
 }

 .schema[open] .schema__summary::before {
   content: "−";
 }

 .schema__summary:hover {
   border-color: var(--line-strong);
   color: var(--text);
 }

 .schema .codeblock {
   margin-top: 14px;
   max-height: 480px;
   overflow: auto;
 }

 /* The quick start. */
 .quickstart {
   display: flex;
   flex-direction: column;
   gap: 40px;
   margin: 0;
   padding: 0;
   list-style: none;
   counter-reset: quickstart;
 }

 .quickstart__step {
   counter-increment: quickstart;
 }

 .quickstart__title {
   display: flex;
   align-items: baseline;
   gap: 12px;
   margin-bottom: 12px;
   font-size: 1.25rem;
   font-weight: 600;
   letter-spacing: -0.015em;
 }

 .quickstart__title::before {
   content: counter(quickstart, decimal-leading-zero);
   font-family: var(--mono);
   font-size: 0.75rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   color: var(--accent);
 }

 .quickstart__body {
   max-width: 62ch;
   margin-bottom: 16px;
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.65;
 }

 .quickstart__aside {
   max-width: 62ch;
   margin-top: 14px;
   color: var(--faint);
   font-size: 0.875rem;
   line-height: 1.6;
 }

 .quickstart__table {
   width: 100%;
   margin-top: 16px;
   border-collapse: collapse;
   font-size: 0.875rem;
 }

 .quickstart__table th,
 .quickstart__table td {
   padding: 9px 12px;
   border-bottom: 1px solid var(--line);
   text-align: left;
 }

 .quickstart__table th {
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .quickstart__table code {
   font-family: var(--mono);
   color: var(--text);
 }

 .quickstart__heading {
   margin-top: 56px;
   margin-bottom: 16px;
   font-size: 1.25rem;
   font-weight: 600;
   letter-spacing: -0.015em;
 }

 .quickstart__links {
   display: flex;
   flex-direction: column;
   gap: 10px;
   margin: 0;
   padding: 0;
   list-style: none;
   color: var(--muted);
   font-size: 0.9375rem;
 }

 /* ---------------------------------------------------------------- */
 /* Surfaces — the six catalog cards                                  */
 /* ---------------------------------------------------------------- */

 .surface {
   display: flex;
   flex-direction: column;
   gap: 14px;
   padding: 22px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--bg-raised);
   box-shadow: var(--hairline);
 }

 .surface__head {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 12px;
 }

 .surface__id {
   font-family: var(--mono);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--accent);
 }

 .surface__statement {
   font-size: 0.9375rem;
   font-weight: 500;
   line-height: 1.5;
 }

 .surface__meta {
   display: flex;
   flex-wrap: wrap;
   gap: 6px;
 }

 .surface__scores {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   gap: 4px 10px;
   font-family: var(--mono);
   font-size: 0.8125rem;
   color: var(--muted);
 }

 .surface__opportunity {
   font-size: 1.375rem;
   font-weight: 600;
   letter-spacing: -0.02em;
   color: var(--text);
 }

 .meter {
   display: flex;
   flex-direction: column;
   gap: 6px;
 }

 .meter__head {
   display: flex;
   justify-content: space-between;
   font-size: 0.6875rem;
   letter-spacing: 0.07em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .meter__track {
   display: block;
   height: 6px;
   border-radius: var(--r-pill);
   background: var(--surface-hover);
   overflow: hidden;
 }

 .meter__fill {
   display: block;
   height: 100%;
   border-radius: var(--r-pill);
   background: var(--accent);
 }

 .meter__fill--positive { background: var(--green); }
 .meter__fill--warning { background: var(--amber); }

 .surface-card {
   container-type: inline-size;
   display: flex;
   flex-direction: column;
   gap: 14px;
   padding: 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
   transition:
     transform 0.2s var(--ease-apple-out),
     border-color 0.2s var(--ease-apple-out);
 }

 .surface-card:hover {
   transform: translateY(-2px);
   border-color: var(--line-strong);
 }

 .surface-card__head {
   display: flex;
   align-items: baseline;
   justify-content: space-between;
   gap: 12px;
 }

 .surface-card__title {
   font-size: 1rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .surface-card__type {
   font-family: var(--mono);
   font-size: 0.6875rem;
   color: var(--faint);
 }

 .surface-card__blurb {
   margin-top: auto;
   color: var(--muted);
   font-size: 0.875rem;
   line-height: 1.55;
 }

 .surface-card .surface {
   background: var(--bg-raised);
 }

 .surface__row + .surface__row {
   padding-top: 12px;
   border-top: 1px solid var(--line);
 }

 .connector-group__title {
   margin-bottom: 16px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.12em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .jobmap {
   display: flex;
   flex-direction: column;
   gap: 6px;
   margin: 0;
   padding: 0;
   list-style: none;
 }

 .jobmap__step {
   display: flex;
   align-items: baseline;
   gap: 10px;
   padding: 9px 12px;
   border-left: 2px solid color-mix(in srgb, var(--accent) 50%, transparent);
   border-radius: 0 var(--r-sm) var(--r-sm) 0;
   background: var(--surface);
   font-size: 0.875rem;
 }

 .jobmap__index {
   font-family: var(--mono);
   font-size: 0.6875rem;
   color: var(--accent);
 }

 .compare {
   display: grid;
   gap: 8px;
   grid-template-columns: 1fr 1fr;
 }

 @container (max-width: 460px) {
   .compare {
     grid-template-columns: 1fr;
   }
 }

 .compare__col {
   padding: 12px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   font-size: 0.8125rem;
   line-height: 1.5;
 }

 .compare__col--after {
   border-color: color-mix(in srgb, var(--green) 22%, transparent);
   background: color-mix(in srgb, var(--green) 6%, transparent);
 }

 .compare__col--before {
   border-color: color-mix(in srgb, var(--red) 20%, transparent);
   background: color-mix(in srgb, var(--red) 6%, transparent);
 }

 .compare__label {
   display: block;
   margin-bottom: 6px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .evidence {
   padding: 12px 14px;
   border-left: 2px solid color-mix(in srgb, var(--accent) 50%, transparent);
   border-radius: 0 var(--r-sm) var(--r-sm) 0;
   background: var(--surface);
 }

 .evidence__quote {
   color: var(--text);
   font-size: 0.875rem;
   font-style: italic;
   line-height: 1.55;
 }

 .evidence__meta {
   display: block;
   margin-top: 8px;
   color: var(--faint);
   font-size: 0.6875rem;
 }

 /* ---------------------------------------------------------------- */
 /* Steps                                                            */
 /* ---------------------------------------------------------------- */

 .steps {
   display: grid;
   gap: 20px;
   grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
   counter-reset: step;
 }

 .step {
   position: relative;
   display: flex;
   flex-direction: column;
   gap: 12px;
   padding: 26px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
   counter-increment: step;
 }

 .step::before {
   content: counter(step, decimal-leading-zero);
   font-family: var(--mono);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   color: var(--accent);
 }

 .step__title {
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .step__body {
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 /* ---------------------------------------------------------------- */
 /* Connectors                                                       */
 /* ---------------------------------------------------------------- */

 .connector-group + .connector-group {
   margin-top: 36px;
 }

 .connector-list {
   display: grid;
   gap: 12px;
   grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 }

 .connector {
   display: flex;
   flex-direction: column;
   gap: 8px;
   padding: 18px 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--surface);
   transition:
     transform 0.18s var(--ease-apple-out),
     border-color 0.18s var(--ease-apple-out);
 }

 .connector:hover {
   transform: translateY(-2px);
   border-color: var(--line-strong);
 }

 .connector__head {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 10px;
 }

 .connector__name {
   font-size: 0.9375rem;
   font-weight: 600;
 }

 .connector__summary {
   color: var(--muted);
   font-size: 0.8125rem;
   line-height: 1.55;
 }

 .connector__env {
   font-family: var(--mono);
   font-size: 0.6875rem;
   color: var(--faint);
 }

 /* ---------------------------------------------------------------- */
 /* Code                                                             */
 /* ---------------------------------------------------------------- */

 .codeblock {
   position: relative;
   margin: 0;
   padding: 20px 22px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--bg-sunken);
   overflow-x: auto;
   font-family: var(--mono);
   font-size: 0.875rem;
   line-height: 1.65;
   color: var(--text);
   tab-size: 2;
 }

 .codeblock code {
   font-family: var(--mono);
   white-space: pre;
 }

 .copy-btn {
   position: absolute;
   top: 10px;
   right: 10px;
   padding: 5px 12px;
   border: 1px solid var(--line-strong);
   border-radius: var(--r-pill);
   background: var(--bg-raised);
   color: var(--muted);
   font-family: var(--font);
   font-size: 0.75rem;
   font-weight: 600;
   opacity: 0;
   transition:
     opacity 0.15s var(--ease-tactile),
     color 0.15s var(--ease-tactile),
     border-color 0.15s var(--ease-tactile);
 }

 .codeblock:hover .copy-btn,
 .copy-btn:focus-visible {
   opacity: 1;
 }

 .copy-btn:hover {
   color: var(--text);
   border-color: var(--line-strong);
 }

 /* Syntax highlighting, server-rendered by Pygments. */
 .highlight {
   margin: 0;
   padding: 20px 22px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--bg-sunken);
   overflow-x: auto;
   font-family: var(--mono);
   font-size: 0.875rem;
   line-height: 1.65;
 }

 .highlight pre {
   margin: 0;
   font-family: var(--mono);
 }

 .highlight code {
   font-family: var(--mono);
   white-space: pre;
 }

 /* ---------------------------------------------------------------- */
 /* Tabs                                                             */
 /* ---------------------------------------------------------------- */

 .tabs__list {
   display: inline-flex;
   gap: 4px;
   padding: 4px;
   border: 1px solid var(--line);
   border-radius: var(--r-pill);
   background: var(--surface);
 }

 .tabs__tab {
   padding: 8px 18px;
   border-radius: var(--r-pill);
   font-size: 0.875rem;
   font-weight: 500;
   color: var(--muted);
   transition:
     background-color 0.15s var(--ease-tactile),
     color 0.15s var(--ease-tactile);
 }

 .tabs__tab[aria-selected="true"] {
   background: var(--surface-hover);
   color: var(--text);
 }

 .tabs__panel {
   margin-top: 20px;
 }

 .tabs__panel[hidden] {
   display: none;
 }

 /* ---------------------------------------------------------------- */
 /* Endpoints                                                        */
 /* ---------------------------------------------------------------- */

 .endpoints {
   display: flex;
   flex-direction: column;
   gap: 0;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   overflow: hidden;
 }

 .endpoint {
   display: grid;
   gap: 4px 20px;
   grid-template-columns: minmax(0, 1fr);
   padding: 18px 22px;
   background: var(--surface);
 }

 .endpoint + .endpoint {
   border-top: 1px solid var(--line);
 }

 @media (min-width: 760px) {
   .endpoint {
     grid-template-columns: 200px minmax(0, 1fr);
     align-items: center;
   }
 }

 .endpoint__name {
   font-size: 0.875rem;
   font-weight: 600;
 }

 .endpoint__url {
   display: flex;
   align-items: center;
   gap: 10px;
   font-family: var(--mono);
   font-size: 0.8125rem;
   color: var(--muted);
   overflow-wrap: anywhere;
 }

 .endpoint__note {
   grid-column: 1 / -1;
   color: var(--faint);
   font-size: 0.8125rem;
   line-height: 1.5;
 }

 /* ---------------------------------------------------------------- */
 /* Tools preview                                                    */
 /* ---------------------------------------------------------------- */

 .tool {
   display: flex;
   flex-direction: column;
   gap: 8px;
   padding: 18px 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--surface);
 }

 .tool__name {
   font-family: var(--mono);
   font-size: 0.875rem;
   font-weight: 600;
   color: var(--accent);
 }

 .tool__purpose {
   color: var(--muted);
   font-size: 0.875rem;
   line-height: 1.55;
 }

 .tool__sig {
   font-family: var(--mono);
   font-size: 0.75rem;
   color: var(--faint);
   overflow-wrap: anywhere;
 }

 /* ---------------------------------------------------------------- */
 /* Status                                                           */
 /* ---------------------------------------------------------------- */

 .status-grid {
   display: grid;
   gap: 20px;
   grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 }

 .status-list {
   display: flex;
   flex-direction: column;
   gap: 12px;
   margin: 0;
   padding: 0;
   list-style: none;
 }

 .status-list li {
   display: flex;
   align-items: baseline;
   gap: 10px;
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.55;
 }

 .status-list li::before {
   content: "";
   flex: none;
   width: 5px;
   height: 5px;
   margin-top: 9px;
   border-radius: 50%;
   background: var(--accent);
 }

 .status-note {
   margin-top: 40px;
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 /* ---------------------------------------------------------------- */
 /* Motion                                                           */
 /* ---------------------------------------------------------------- */

 @keyframes hero-in {
   from {
     opacity: 0;
     transform: translateY(10px);
     filter: blur(4px);
   }
   to {
     opacity: 1;
     transform: none;
     filter: blur(0);
   }
 }

 @keyframes reveal-up {
   from {
     opacity: 0;
     transform: translateY(24px);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }

 @keyframes surface-in {
   from {
     opacity: 0;
     transform: translateY(10px) scale(0.985);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }

 @keyframes caret-blink {
   0%, 45% { opacity: 1; }
   46%, 100% { opacity: 0; }
 }

 .hero__eyebrow { animation: hero-in 0.7s var(--ease-apple-out) both; }
 .hero__title    { animation: hero-in 0.7s var(--ease-apple-out) 0.09s both; }
 .hero__sub      { animation: hero-in 0.7s var(--ease-apple-out) 0.18s both; }
 .hero__actions  { animation: hero-in 0.7s var(--ease-apple-out) 0.27s both; }
 .hero__cue      { animation: hero-in 0.7s var(--ease-apple-out) 0.36s both; }

 /* Reveal-on-scroll. Content is visible by default; the observer opts it
    into the hidden state only after it loads, so no-JS readers never lose
    anything. */
 .js-reveal [data-reveal] {
   opacity: 0;
   transform: translateY(24px);
   transition:
     opacity 0.8s var(--ease-apple-out),
     transform 0.8s var(--ease-apple-out);
 }

 .js-reveal [data-reveal].is-visible {
   opacity: 1;
   transform: none;
 }

 @media (prefers-reduced-motion: reduce) {
   html {
     scroll-behavior: auto;
   }

   *,
   *::before,
   *::after {
     animation-duration: 0.001ms !important;
     animation-iteration-count: 1 !important;
     transition-duration: 0.001ms !important;
     scroll-behavior: auto !important;
   }

   .js-reveal [data-reveal] {
     opacity: 1;
     transform: none;
   }
 }

 /* ---------------------------------------------------------------- */
 /* Responsive                                                       */
 /* ---------------------------------------------------------------- */

 @media (max-width: 860px) {
   .site-nav {
     display: none;
   }
 }

 @media (max-width: 640px) {
   .compare {
     grid-template-columns: 1fr;
   }

   .gap__row {
     grid-template-columns: 78px 1fr 34px;
     gap: 10px;
   }
 }

