     if (!scope) return null;
     var codes = scope.querySelectorAll("code");
     for (var i = 0; i < codes.length; i += 1) {
       var code = codes[i];
       if (code.contains(button) || button.contains(code)) continue;
       return code;
     }
     return null;
   }

