import { apiUrl } from "../bridge/desktopBridge";
import { getStudioBff } from "../bff/index";
import type {
  AddConnectorPayload,
  AddOutcomePayload,
  AddStepPayload,
  CanvasData,
  ChangelogData,
  ChatStreamRequest,
  ConnectorHealth,
  ConnectorListItem,
  ConnectorOperationResponse,
  ConnectorPreset,
  Conversation,
  ConversationTree,
  CreateJobPayload,
  Job,
  LatestConversation,
  LlmHealth,
  McpHealth,
  Observation,
  ObservationKind,
  ObservationStatus,
  Outcome,
  Step,
  StudioConfig,
  StudioError,
} from "../types";
import { createSseParser, type RawSseEvent } from "./sse";

/** A failure the sidecar reported, kept whole so the UI can show it. */
export class StudioApiError extends Error {
  readonly error: StudioError;
  readonly status: number;

  constructor(error: StudioError, status = 0) {
    super(error.message);
    this.name = "StudioApiError";
    this.error = error;
    this.status = status;
  }
}

/** Network or sidecar-proxy failures are transport failures; application errors are not. */
export function isTransportFailure(error: unknown): boolean {
  if (error instanceof StudioApiError) {
    return error.status === 502 || error.status === 503 || error.status === 504;
  }
  if (error instanceof TypeError) {
    return true;
  }
  if (error && typeof error === "object" && (error as { name?: string }).name === "NetworkError") {
    return true;
  }
  return false;
