export async function streamChat(
  request: ChatStreamRequest,
  onEvent: ChatEventHandler,
  signal?: AbortSignal,
): Promise<void> {
  try {
    const response = await fetch(apiUrl("/api/chat"), {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "text/event-stream" },
      body: JSON.stringify({
        ...request,
        messages: request.messages.reduce<{
          id: string;
          role: "user" | "assistant";
          content: string;
          parent_id: string | null;
        }[]>((history, message) => {
          if (message.role === "notice") {
            return history;
          }
          const parent_id = history.at(-1)?.id ?? null;
          history.push({
            id: message.id,
            role: message.role,
            content: message.content,
            parent_id,
          });
          return history;
        }, []),
        attachments: request.attachments?.map((attachment) => ({
          name: attachment.name,
          content_type: attachment.contentType,
          size: attachment.size,
          ...(attachment.text ? { text: attachment.text } : {}),
          ...(attachment.dataUrl ? { data_url: attachment.dataUrl } : {}),
        })),
      }),
      signal,
    });

    if (!response.ok || !response.body) {
      throw await studioError(response);
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    const parser = createSseParser();

    for (;;) {
      const { value, done } = await reader.read();
      if (done) {
        break;
      }
      for (const event of parser.push(decoder.decode(value, { stream: true }))) {
        onEvent(event);
      }
    }
  } catch (error) {
    if (error instanceof StudioApiError) {
      throw error;
    }
    if (error instanceof Error && error.name === "AbortError") {
      throw error;
    }
    if (!isTransportFailure(error)) {
      throw error;
    }
    const bff = await getStudioBff();
    await bff.chat.stream(request, onEvent, signal);
  }
}

