  id: string,
  headId: string | null,
): Promise<StoredConversation> {
  const conversation = this.conversations.get(id);
  if (!conversation) {
    throw new Error(`Conversation ${id} not found`);
  }
  const now = nowIso();
  const next: StoredConversation = {
    ...conversation,
    head_id: headId,
    updated_at: now,
  };
  this.conversations.set(id, next);
  return next;
}

