import { IndexedDbLocalStore } from "./indexedDbStore";

async function makeStore() {
  const store = await IndexedDbLocalStore.open();
  return store;
}

async function clearDb() {
  if (typeof indexedDB !== "undefined") {
    await indexedDB.deleteDatabase("agentic-odi-studio");
  }
}

afterEach(async () => {
  await clearDb();
});

describe("IndexedDbLocalStore", () => {
  it("persists jobs across store instances", async () => {
    const store = await makeStore();
    await store.putJob({
      id: "j-1",
      name: "Job",
      description: "d",
      seq: 1,
      created_at: "2026-01-01T00:00:00Z",
      updated_at: "2026-01-01T00:00:00Z",
    });
    store.close();

    const next = await makeStore();
    const jobs = await next.listJobs();
    expect(jobs).toHaveLength(1);
    expect(jobs[0].name).toBe("Job");
    next.close();
  });

  it("orders jobs by seq", async () => {
    const store = await makeStore();
    await store.putJob({
      id: "j-2",
      name: "B",
      description: "",
      seq: 2,
      created_at: "2026-01-01T00:00:00Z",
      updated_at: "2026-01-01T00:00:00Z",
    });
    await store.putJob({
      id: "j-1",
      name: "A",
      description: "",
      seq: 1,
      created_at: "2026-01-01T00:00:00Z",
      updated_at: "2026-01-01T00:00:00Z",
    });

    const jobs = await store.listJobs();
    expect(jobs.map((j) => j.name)).toEqual(["A", "B"]);
    store.close();
  });

  it("supports conversations, turns, and head", async () => {
    const store = await makeStore();
    await store.putConversation({
      id: "c-1",
      title: "Chat",
      created_at: "2026-01-01T00:00:00Z",
      updated_at: "2026-01-01T00:00:00Z",
      head_id: null,
    });
    await store.appendTurn({
      conversation_id: "c-1",
      role: "user",
      content: "hi",
      created_at: "2026-01-01T00:00:00Z",
      message_id: "m-1",
      parent_id: null,
    });
    await store.appendTurn({
      conversation_id: "c-1",
      role: "assistant",
      content: "hello",
      created_at: "2026-01-01T00:00:00Z",
      message_id: "m-2",
      parent_id: "m-1",
    });

    const tree = await store.conversationTree("c-1");
    expect(tree.messages.map((m) => m.message_id)).toEqual(["m-1", "m-2"]);
    expect(tree.head_id).toBe("m-2");

    await store.setConversationHead("c-1", "m-1");
    const again = await store.conversationTree("c-1");
    expect(again.head_id).toBe("m-1");
    store.close();
  });
});

import { describe, expect, it } from "vitest";

import { MemoryLocalStore } from "../store/memoryStore";
import { LocalDataService } from "../data/localDataService";
import { LocalMemoryService } from "../memory/localMemoryService";
import { ChatOrchestrator } from "./orchestrator";
import type { ChatMessage } from "../../types";
import type { RawSseEvent } from "../../api/sse";

function makeBff() {
  const store = new MemoryLocalStore();
  const data = new LocalDataService(store);
  const memory = new LocalMemoryService(store);
  return new ChatOrchestrator(store, data, memory);
}

function collectEvents() {
  const events: RawSseEvent[] = [];
  return { events, onEvent: (event: RawSseEvent) => events.push(event) };
}

function lastUserMessage(content: string, id = "u-1"): ChatMessage {
  return { id, parentId: null, role: "user", content };
}

describe("ChatOrchestrator deterministic mode", () => {
  it("answers about an empty canvas", async () => {
    const orchestrator = makeBff();
    const { events, onEvent } = collectEvents();
    await orchestrator.stream(
      { base_url: "http://localhost:8001/v1", api_key: "local", model: "local", messages: [lastUserMessage("how many jobs?")] },
      onEvent,
    );

    const messages = events.filter((e) => e.event === "message");
    expect(messages[messages.length - 1].data.content).toContain("canvas has 0 jobs");
  });

  it("adds a job via the deterministic assistant", async () => {
    const orchestrator = makeBff();
    const { events, onEvent } = collectEvents();
    await orchestrator.stream(
      { base_url: "http://localhost:8001/v1", api_key: "local", model: "local", messages: [lastUserMessage("add job Onboard customers")] },
      onEvent,
    );

    const toolEvents = events.filter((e) => e.event === "tool");
    expect(toolEvents.some((e) => e.data.name === "create_job" && e.data.status === "running")).toBe(true);
    expect(toolEvents.some((e) => e.data.name === "create_job" && e.data.status === "ok")).toBe(true);
    const dirty = events.some((e) => e.event === "canvas_dirty");
    expect(dirty).toBe(true);

    const data = new LocalDataService(new MemoryLocalStore());
    // The store is shared through the orchestrator; check via a fresh fetch on same store is not possible here,
    // so assert the message confirms creation.
    const created = events.filter((e) => e.event === "message").map((e) => e.data.content);
    expect(created.some((c) => c.includes("Job \u201cOnboard customers\u201d created."))).toBe(true);
  });

  it("adds an outcome and computes opportunity score", async () => {
    const orchestrator = makeBff();
    const { events, onEvent } = collectEvents();
    await orchestrator.stream(
      { base_url: "http://localhost:8001/v1", api_key: "local", model: "local", messages: [lastUserMessage("add job Onboard customers")] },
      onEvent,
    );
    await orchestrator.stream(
      { base_url: "http://localhost:8001/v1", api_key: "local", model: "local", messages: [lastUserMessage("add outcome Reduce setup time importance 8 satisfaction 3")] },
      onEvent,
    );

    const created = events.filter((e) => e.event === "message").map((e) => e.data.content);
    expect(created.some((c) => c.includes("opportunity 13"))).toBe(true);
  });

  it("saves to memory and emits a memory event", async () => {
    const orchestrator = makeBff();
    const { events, onEvent } = collectEvents();
    await orchestrator.stream(
      { base_url: "http://localhost:8001/v1", api_key: "local", model: "local", messages: [lastUserMessage("remember the customer hates long setup")] },
      onEvent,
    );

    const memoryEvents = events.filter((e) => e.event === "memory");
    expect(memoryEvents.length).toBeGreaterThan(0);
    const confirmed = events.filter((e) => e.event === "tool" && e.data.name === "remember" && e.data.status === "ok");
    expect(confirmed.length).toBe(1);
  });

  it("renders a valid opportunity board", async () => {
    const orchestrator = makeBff();
    const { events, onEvent } = collectEvents();
    await orchestrator.stream(
      { base_url: "http://localhost:8001/v1", api_key: "local", model: "local", messages: [lastUserMessage("add job Onboard customers")] },
      onEvent,
    );
    await orchestrator.stream(
      { base_url: "http://localhost:8001/v1", api_key: "local", model: "local", messages: [lastUserMessage("add outcome Reduce setup time importance 8 satisfaction 3")] },
      onEvent,
    );
    await orchestrator.stream(
      { base_url: "http://localhost:8001/v1", api_key: "local", model: "local", messages: [lastUserMessage("render the opportunity board")] },
      onEvent,
    );

    const uiEvents = events.filter((e) => e.event === "ui");
    expect(uiEvents.length).toBe(1);
    const spec = uiEvents[0].data.spec as { type: string; props: { outcomes: unknown[] } };
    expect(spec.type).toBe("opportunity-board");
    expect(spec.props.outcomes).toHaveLength(1);
    expect(spec.props.outcomes[0]).toMatchObject({
      statement: "Reduce setup time",
      importance: 8,
      satisfaction: 3,
      opportunityScore: 13,
    });
  });

  it("persists user and assistant turns with ids", async () => {
    const orchestrator = makeBff();
    const { events, onEvent } = collectEvents();
    await orchestrator.stream(
      { base_url: "http://localhost:8001/v1", api_key: "local", model: "local", messages: [lastUserMessage("add job Onboard customers", "u-1")] },
      onEvent,
    );

    const conversation = events.find((e) => e.event === "conversation");
    expect(conversation).toBeDefined();
    expect(conversation!.data.id).toBeTruthy();
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { fetchCanvas, fetchMemory, isTransportFailure, streamChat } from "./studioApi";

const bff = {
  data: { fetchCanvas: vi.fn() },
  memory: { listObservations: vi.fn() },
  chat: { stream: vi.fn() },
};

vi.mock("../bff/index", () => ({
  getStudioBff: vi.fn(() => Promise.resolve(bff)),
}));

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

beforeEach(() => {
  vi.stubGlobal("fetch", vi.fn(async () => jsonResponse({})));
  vi.mocked(bff.data.fetchCanvas).mockReset();
  vi.mocked(bff.memory.listObservations).mockReset();
  vi.mocked(bff.chat.stream).mockReset();
});

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("isTransportFailure", () => {
  it("treats 502 without a sidecar error body as transport", () => {
    expect(isTransportFailure({ status: 502, fromSidecar: false } as any)).toBe(true);
  });

  it("treats a sidecar 502 with a structured error as not transport", () => {
    expect(isTransportFailure({ status: 502, fromSidecar: true } as any)).toBe(false);
  });

  it("treats network errors as transport", () => {
    expect(isTransportFailure(new TypeError("failed to fetch"))).toBe(true);
  });
});

describe("fetchCanvas fallback", () => {
  it("falls back to the local BFF when the sidecar returns 502", async () => {
    vi.mocked(fetch).mockResolvedValueOnce(jsonResponse({ error: { code: "mcp_unreachable", message: "down", retryable: true } }, 502));
    vi.mocked(bff.data.fetchCanvas).mockResolvedValueOnce({ jobs: [], steps: [], outcomes: [], source: "local" });

    const canvas = await fetchCanvas("http://mcp");
    expect(canvas.source).toBe("local");
    expect(bff.data.fetchCanvas).toHaveBeenCalled();
  });

  it("does not fall back for a sidecar 422", async () => {
    vi.mocked(fetch).mockResolvedValueOnce(jsonResponse({ error: { code: "validation", message: "bad" } }, 422));
    await expect(fetchCanvas("http://mcp")).rejects.toThrow();
    expect(bff.data.fetchCanvas).not.toHaveBeenCalled();
  });
});

describe("fetchMemory fallback", () => {
  it("falls back to the local BFF when the sidecar returns 502", async () => {
    vi.mocked(fetch).mockResolvedValueOnce(jsonResponse({ detail: "Sidecar unreachable" }, 502));
    vi.mocked(bff.memory.listObservations).mockResolvedValueOnce([]);

    await fetchMemory();
    expect(bff.memory.listObservations).toHaveBeenCalled();
  });
});

describe("streamChat fallback", () => {
  it("falls back to the local BFF when the sidecar returns 502", async () => {
    vi.mocked(fetch).mockResolvedValueOnce(jsonResponse({ detail: "SIDECAR_URL is not configured" }, 502));
    vi.mocked(bff.chat.stream).mockResolvedValueOnce(undefined);

    await streamChat(
      { base_url: "", api_key: "", model: "", mcp_url: "", messages: [] },
      () => {},
    );
    expect(bff.chat.stream).toHaveBeenCalled();
  });

  it("does not fall back for a sidecar 500", async () => {
    vi.mocked(fetch).mockResolvedValueOnce(jsonResponse({ error: { code: "internal", message: "boom" } }, 500));
    await expect(
      streamChat({ base_url: "", api_key: "", model: "", mcp_url: "", messages: [] }, () => {}),
    ).rejects.toThrow();
    expect(bff.chat.stream).not.toHaveBeenCalled();
  });
});

