+    const steps = await this.listSteps();
+    const outcomes = await this.listOutcomes();
+    const observations = await this.listObservations();
+    const conversations = await this.listConversations();
+    return {
+      version: 1,
+      jobs,
+      steps,
+      outcomes,
+      observations,
+      conversations,
+      turns: [...this.turns],
+    };
+  }
